            "kind": "p",
            "text": "छत के एक हिस्से की क्षैतिज दूरी 4 मीटर और ऊर्ध्वाधर ऊँचाई 3 मीटर है। यहाँ [[b=4\\text{ m}]] और [[a=3\\text{ m}]]। [[\\cot(A)=4/3]], इसलिए [[\\boxed{\\cot(A)\\approx1.3333}]]: क्षैतिज दूरी ऊर्ध्वाधर ऊँचाई की लगभग 1.3333 गुना है। यह अनुपात पूर्ण संरचनात्मक या छत-संहिता आकलन नहीं है।"
