            "kind": "p",
            "text": "Когда угол [[A]] отсчитывается от горизонтали, прилежащий катет может обозначать горизонтальный отрезок, а противолежащий катет может обозначать вертикальный подъём. Тогда [[\\cot(A)=\\frac{\\text{Horizontal run}}{\\text{Vertical rise}}]]. Тангенс даёт то же соотношение в перевёрнутом виде: подъём, делённый на отрезок. Такое прочтение «отрезок на подъём» делает котангенс естественным отношением для вопросов вроде «какое горизонтальное расстояние приходится на какую высоту?», и оно зависит от выбранного исходного угла и геометрии ситуации."
