      "cot-recover": "So finden Sie einen Winkel bei bekanntem Kotangens",
      "cot-mistakes": "Häufige Fehler bei der Kotangensberechnung",
      "cot-verify": "So prüfen Sie, ob Ihr Kotangensergebnis gültig ist",
      "cot-vs": "Kotangens im Vergleich zu Tangens, Sinus und Kosinus",
